package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string
var WsTotal decimal.Decimal
var WsGrand decimal.Decimal
var WsNewCount int64
var WsShipCount int64
var WsCancelCount int64
var WsInvalid int64
var WsBadQty int64
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRecords []string
var orderIdx int
var currentRec OrderRec
var atEnd bool

func main() {
	// INITIAL VALUES
	WsEofFlag = "N"
	WsTotal = decimal.NewFromInt(0)
	WsGrand = decimal.NewFromInt(0)
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0

	// OPEN INPUT
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		orderRecords = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			// LINE SEQUENTIAL: keep as is (without newline)
			orderRecords = append(orderRecords, line)
		}
		f.Close()
	}
	orderIdx = 0
	atEnd = false
	WsEofFlag = "N"

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !INPUT_DONE() {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}

func INPUT_DONE() bool {
	return WsEofFlag == "Y"
}

func READ_PARA() {
	if orderIdx >= len(orderRecords) {
		WsEofFlag = "Y"
		atEnd = true
		return
	}
	line := orderRecords[orderIdx]
	orderIdx++
	// pad with spaces on the right to record length 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse
	orId := line[0:5]
	orStat := line[5:6]
	orQtyStr := line[6:9]
	orPriceStr := line[9:15]

	var qty int64
	trimmed := strings.TrimSpace(orQtyStr)
	if trimmed == "" {
		qty = 0
	} else {
		// orQtyStr may contain spaces, strip them
		// If it contains non-digit, Atoi will fail -> treat as 0
		// Remove spaces
		clean := strings.TrimSpace(orQtyStr)
		// If clean still has spaces inside, remove
		clean = strings.ReplaceAll(clean, " ", "")
		if clean == "" {
			qty = 0
		} else {
			v, err := strconv.ParseInt(clean, 10, 64)
			if err != nil {
				qty = 0
			} else {
				qty = v
			}
		}
	}
	// price: digits only, implied V99
	priceDigits := strings.TrimSpace(orPriceStr)
	// But if original had spaces padded, after pad we have spaces; TrimSpace removes them
	// For proper numeric, we need to parse the 6-char field as digits.
	// If it was short and padded, spaces become missing digits -> should be zero
	// Use the raw substring: keep only digits, if spaces treat as zero
	rawPrice := line[9:15]
	// rawPrice may contain spaces; for each char if not digit, treat as zero?
	// Instead, if trimmed == "" => 0, else parse digits
	var priceInt int64
	cleanPrice := ""
	for _, ch := range rawPrice {
		if ch >= '0' && ch <= '9' {
			cleanPrice += string(ch)
		} else if ch == ' ' {
			// spaces that are padding of short record: they correspond to missing digits -> treat as space -> ignore?
			// But for COBOL short line padded with spaces, those spaces are not numeric; they should be considered as spaces/zero?
			// Pad on right means missing PRICE digits become spaces -> effectively zero?
			// We'll treat spaces as not contributing; but to get correct digit count, we need to consider that padded spaces are not zeros but spaces.
			// For numeric field, spaces would be considered 0 in many COBOL? We'll treat as 0.
			cleanPrice += "0"
		}
	}
	if cleanPrice == "" {
		priceInt = 0
	} else {
		v, err := strconv.ParseInt(cleanPrice, 10, 64)
		if err != nil {
			priceInt = 0
		} else {
			priceInt = v
		}
	}
	// Alternative: if the original line was shorter than 15, the price field partially missing -> we already padded with spaces -> cleanPrice will have zeros for missing
	// For lines that are exactly 15, cleanPrice is exactly digits.

	priceDec := decimal.New(priceInt, -2)

	currentRec = OrderRec{
		OrId:    orId,
		OrStat:  orStat,
		OrQty:   qty,
		OrPrice: priceDec,
	}
	WsEofFlag = "N"
	atEnd = false
}

func PROCESS_PARA() {
	// MOVE 0 TO WS-TOTAL
	WsTotal = decimal.NewFromInt(0)

	// EVALUATE TRUE
	if currentRec.OrQty == 0 {
		WsBadQty = storeInt(WsBadQty+1, 2)
		// DISPLAY OR-ID " BAD QTY"
		fmt.Printf("%s BAD QTY\n", currentRec.OrId)
	} else if currentRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE  (truncated)
		qtyDec := decimal.NewFromInt(currentRec.OrQty)
		prod := qtyDec.Mul(currentRec.OrPrice)
		WsTotal = storeDecimal(prod.Truncate(2), 8, 2)
		WsNewCount = storeInt(WsNewCount+1, 2)
		SHOW_PARA()
	} else if currentRec.OrStat == "S" {
		// COMPUTE WS-TOTAL ROUNDED = OR-QTY * OR-PRICE * 1.05
		qtyDec := decimal.NewFromInt(currentRec.OrQty)
		prod := qtyDec.Mul(currentRec.OrPrice)
		// multiply by 1.05 = 105/100
		prod = prod.Mul(decimal.New(105, -2))
		rounded := prod.Round(2)
		WsTotal = storeDecimal(rounded, 8, 2)
		WsShipCount = storeInt(WsShipCount+1, 2)
		SHOW_PARA()
	} else if currentRec.OrStat == "C" {
		WsCancelCount = storeInt(WsCancelCount+1, 2)
		SHOW_PARA()
	} else {
		WsInvalid = storeInt(WsInvalid+1, 2)
		fmt.Printf("%s BAD STATUS %s\n", currentRec.OrId, currentRec.OrStat)
	}
	// ADD WS-TOTAL TO WS-GRAND
	WsGrand = storeDecimal(WsGrand.Add(WsTotal), 10, 2)
	READ_PARA()
}

func SHOW_PARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(currentRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(currentRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", currentRec.OrId, currentRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatInt(WsNewCount, 2), formatInt(WsShipCount, 2), formatInt(WsCancelCount, 2))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatInt(WsInvalid, 2), formatInt(WsBadQty, 2))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

// helpers

func storeInt(v int64, digits int) int64 {
	if digits >= 18 {
		return v
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, handle negative? keep sign
	if v < 0 {
		neg := -v
		neg = neg % mod
		return -neg
	}
	return v % mod
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// truncate to scale already done by caller (or round)
	// apply overflow: keep low-order intDigits
	v = v.Truncate(int32(scale))
	// compute integer part modulo
	// total scaled integer = v * 10^scale
	pow10scale := decimal.New(1, int32(scale))
	scaled := v.Mul(pow10scale) // integer value

	// truncate toward zero to integer
	scaled = scaled.Truncate(0)

	// For overflow, we need modulo 10^(intDigits+scale) ??? Actually integer digits capacity applies to integer part only.
	// Equivalent to: integer part = trunc(v) modulo 10^intDigits, fractional unchanged
	// So we can compute integer part separately.
	// integerPart = trunc(v)  (toward zero)
	intPart := v.Truncate(0)
	fracPart := v.Sub(intPart)

	// modulo for intPart
	modInt := decimal.New(1, int32(intDigits)) // 10^intDigits
	// for positive: intPart % modInt, for negative: similar keeping sign
	// decimal.Mod not directly, do via IntPart if fits int64? intDigits up to 10 fits 10^10 < 2^63
	// Use integer arithmetic via decimal division
	// Compute intPart truncated modulo
	// Use: intPart = intPart - trunc(intPart/modInt)*modInt
	if intDigits <= 18 {
		// fast path using int64 when possible, but decimal may be large
		// Do decimal approach: q = intPart.Div(modInt).Truncate(0)
		// then r = intPart - q*modInt
		if !intPart.IsZero() {
			q := intPart.Div(modInt).Truncate(0)
			intPart = intPart.Sub(q.Mul(modInt))
		}
		// recombine
		v = intPart.Add(fracPart)
		return v
	}
	return v
}

func formatInt(v int64, width int) string {
	s := strconv.FormatInt(v, 10)
	// keep low-order digits if overflow
	if len(s) > width {
		// for negative include sign? not needed
		if s[0] == '-' {
			s = "-" + s[len(s)-width+1:]
		} else {
			s = s[len(s)-width:]
		}
	}
	if len(s) < width {
		// zero pad on left, for negative: "-00..."?
		if v < 0 {
			// v is negative, s includes '-'
			digits := s[1:]
			padded := strings.Repeat("0", width-len(s)) + digits
			// COBOL would show sign? but not needed
			return "-" + padded[len(padded)-width+1:]
		}
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func formatEdited(v decimal.Decimal, pic string) string {
	// Determine decimal places: count of 9/Z after '.'
	dotIdx := strings.Index(pic, ".")
	intPic := pic
	decPic := ""
	decDigits := 0
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
		for _, ch := range decPic {
			if ch == '9' || ch == 'Z' || ch == 'z' {
				decDigits++
			}
		}
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' || ch == 'z' {
			intDigits++
		}
	}
	// Prepare scaled value truncated to decDigits (MOVE already ensures)
	// For formatting, ensure we truncate/round? The value passed already has correct scale
	// But we ensure truncation to decDigits for safety
	// Work with absolute value for formatting; sign not needed (all positive)
	isNeg := v.IsNegative()
	if isNeg {
		v = v.Neg()
	}
	v = v.Truncate(int32(decDigits))

	// Build integer and fractional parts after overflow handling (overflow already handled in store,
	// but edited overflow also drops high digits; we apply here too)
	// Integer part modulo 10^intDigits
	intPart := v.Truncate(0)
	// modulo
	if intDigits > 0 {
		modInt := decimal.New(1, int32(intDigits))
		if !intPart.IsZero() {
			q := intPart.Div(modInt).Truncate(0)
			intPart = intPart.Sub(q.Mul(modInt))
			// intPart may be negative if original negative? but we made positive
		}
		// ensure non-negative
		if intPart.IsNegative() {
			intPart = intPart.Neg()
		}
	}
	fracPart := v.Sub(v.Truncate(0))
	// fracPart may be negative? not here
	if fracPart.IsNegative() {
		fracPart = fracPart.Neg()
	}
	// Rebuild fractional integer: frac *10^decDigits
	var fracInt int64 = 0
	if decDigits > 0 {
		pow := decimal.New(1, int32(decDigits))
		fv := fracPart.Mul(pow).Truncate(0)
		// fv should be integer 0..10^decDigits-1
		fracInt = fv.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
	}
	intInt := intPart.IntPart()
	if intInt < 0 {
		intInt = -intInt
	}
	// Build digit strings
	intStr := strconv.FormatInt(intInt, 10)
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	} else if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	fracStr := ""
	if decDigits > 0 {
		fracStr = strconv.FormatInt(fracInt, 10)
		if len(fracStr) < decDigits {
			fracStr = strings.Repeat("0", decDigits-len(fracStr)) + fracStr
		}
	}

	// Map to picture
	// For integer part, walk pic chars
	var out strings.Builder
	digitIdx := 0 // index into intStr
	seenSignificant := false
	// Need to know for each Z position whether digit is non-zero after this point? For suppression we just use seenSignificant flag
	for _, ch := range intPic {
		if ch == 'Z' || ch == 'z' {
			d := intStr[digitIdx]
			digitIdx++
			if d != '0' {
				seenSignificant = true
				out.WriteByte(d)
			} else {
				if seenSignificant {
					out.WriteByte('0')
				} else {
					// check if any later non-zero digit exists? But seenSignificant will become true later, we still want to keep this as space
					// So space
					out.WriteByte(' ')
				}
			}
		} else if ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			// 9 always prints, and if non-zero marks significant
			if d != '0' {
				seenSignificant = true
			} else {
				// even zero at 9 position is considered printed; but for comma logic, does zero at 9 count as significant?
				// If integer is zero, the '9' zero is the significant digit representing zero.
				// For comma suppression, a zero forced by 9 should count as significant for following commas? But there is no comma after last digit.
				// So set significant to true because we have printed a digit (even zero) at mandatory position? However for ZERO value, we want commas suppressed.
				// COBOL: for zero, the mandatory 9 prints 0 but commas remain spaces.
				// So we should NOT consider zero at 9 as making commas significant if it's the zero value? But there are no commas after it.
				// So irrelevant.
				if len(intPic) > 0 {
					// Determine if this is the last digit position and all digits are zero, still not needed
				}
			}
			// For zero value, we still want to indicate significance for future? No future.
			// To handle cases where 9 zero is before later digits? But 9 only appears at last integer position in given pics, so no.
			if d == '0' && !seenSignificant {
				// This is the final mandatory zero for value zero: we should mark significant so that we don't suppress it? Already printing.
				// But for consistency, keep seenSignificant false for comma logic? Doesn't matter.
			}
			if d != '0' {
				seenSignificant = true
			}
			out.WriteByte(d)
		} else if ch == ',' {
			if seenSignificant {
				out.WriteByte(',')
			} else {
				out.WriteByte(' ')
			}
		} else {
			// other literals (should not in int part)
			out.WriteRune(ch)
		}
	}
	if decDigits > 0 {
		out.WriteByte('.')
		// decPic is all 9's, just output fracStr
		// But if decPic contained Z, similar logic; here it's 9s
		for i, ch := range decPic {
			if ch == '9' || ch == 'Z' || ch == 'z' {
				if i < len(fracStr) {
					out.WriteByte(fracStr[i])
				} else {
					out.WriteByte('0')
				}
			} else {
				out.WriteRune(ch)
			}
		}
	}
	res := out.String()
	// Ensure length equals pic length (pad if needed)
	if len(res) < len(pic) {
		res = strings.Repeat(" ", len(pic)-len(res)) + res
	}
	if isNeg {
		// place minus sign at leftmost? Not needed for this program
		// COBOL would show minus, but not in tests
	}
	return res
}

