		decPic = pic[dotIdx+1:]
		for _, ch := range decPic {
			if ch == '9' || ch == 'Z' || ch == 'z' {
				decDigits++
			}
		}
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' || ch == 'z' {
			intDigits++
		}
	}
	isNeg := v.IsNegative()
	if isNeg {
		v = v.Neg()
	}
	v = v.Truncate(int32(decDigits))
	intPart := v.Truncate(0)
	if intDigits > 0 {
		modInt := decimal.New(1, int32(intDigits))
		if !intPart.IsZero() {
			q := intPart.Div(modInt).Truncate(0)
			intPart = intPart.Sub(q.Mul(modInt))
		}
		if intPart.IsNegative() {
			intPart = intPart.Neg()
		}
	}
	fracPart := v.Sub(v.Truncate(0))
	if fracPart.IsNegative() {
		fracPart = fracPart.Neg()
	}
	var fracInt int64 = 0
	if decDigits > 0 {
		pow := decimal.New(1, int32(decDigits))
		fv := fracPart.Mul(pow).Truncate(0)
		fracInt = fv.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
	}
	intInt := intPart.IntPart()
	if intInt < 0 {
		intInt = -intInt
	}
	intStr := strconv.FormatInt(intInt, 10)
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	} else if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	fracStr := ""
	if decDigits > 0 {
		fracStr = strconv.FormatInt(fracInt, 10)
		if len(fracStr) < decDigits {
			fracStr = strings.Repeat("0", decDigits-len(fracStr)) + fracStr
		}
	}
	var out strings.Builder
	digitIdx := 0
	seenSignificant := false
	for _, ch := range intPic {
		if ch == 'Z' || ch == 'z' {
			d := intStr[digitIdx]
			digitIdx++
			if d != '0' {
				seenSignificant = true
				out.WriteByte(d)
			} else {
				if seenSignificant {
					out.WriteByte('0')
				} else {
					out.WriteByte(' ')
				}
			}
		} else if ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			if d != '0' {
				seenSignificant = true
			}
			out.WriteByte(d)
		} else if ch == ',' {
			if seenSignificant {
				out.WriteByte(',')
			} else {
				out.WriteByte(' ')
			}
		} else {
			out.WriteRune(ch)
		}
	}
	if decDigits > 0 {
		out.WriteByte('.')
		for i, ch := range decPic {
			if ch == '9' || ch == 'Z' || ch == 'z' {
				if i < len(fracStr) {
					out.WriteByte(fracStr[i])
				} else {
					out.WriteByte('0')
				}
			} else {
				out.WriteRune(ch)
			}
		}
	}
	res := out.String()
	if len(res) < len(pic) {
		res = strings.Repeat(" ", len(pic)-len(res)) + res
	}
	return res
}
